import {LESSONS,lessonIds,topicIds,routeFor} from './catalog.js';
import {BRIDGES,bridgeIds,sessionMeta,sessionTasks,bridgeEdgeKey,sourceBridge} from './bridges.js';
import {freshLesson,validateLesson,mergeLesson,lessonSummary} from './state.js';
import {inspect} from './tasks.js';
import {ACTIVITIES} from '../exploration-content.js';
import {ROUTE_STEPS} from '../journey-model.js';
const stamp=()=>new Date().toISOString(),uuid=()=>globalThis.crypto.randomUUID();
const obj=o=>!!o&&typeof o==='object'&&!Array.isArray(o),validDate=s=>typeof s==='string'&&/^\d{4}-\d\d-\d\dT/.test(s)&&Number.isFinite(Date.parse(s));
const event=(kind,at,extra={})=>({id:uuid(),kind,at,...extra});
export const freshDaily=()=>({bridges:{},questions:[],continuation:null});
export function dayKey(at=new Date(),timeZone=Intl.DateTimeFormat().resolvedOptions().timeZone){const parts=new Intl.DateTimeFormat('en-CA',{timeZone,year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(new Date(at));return ['year','month','day'].map(k=>parts.find(p=>p.type===k).value).join('-');}
export function sessionRecord(state,id){return BRIDGES[id]?state.daily?.bridges[id]:state.lessons?.[id];}
export function rememberSession(state,id,questionId=null,at=stamp()){state.daily??=freshDaily();state.daily.continuation={id,questionId,at};}
export function captureSession(record,ui=record.ui||{}){return {record:structuredClone(record),ui:{spread:ui.spread?1:0,view:ui.view||null,camera:ui.camera?structuredClone(ui.camera):null}};}
export function validateScene(raw){if(raw===null||raw===undefined)return null;if(!obj(raw)||!obj(raw.record)||!sessionMeta(raw.record.id)||!obj(raw.ui))throw new Error('问题现场格式无效。');const r=validateLesson(raw.record,raw.record.id,{allowBridge:true}),u=raw.ui;
 if(![0,1].includes(u.spread)||![null,'tally','picture','bar','block','table','list'].includes(u.view))throw new Error('问题现场显示无效。');
 const v=a=>Array.isArray(a)&&a.length===3&&a.every(n=>Number.isFinite(n)&&Math.abs(n)<1000);
 if(u.camera!==null&&(!obj(u.camera)||!v(u.camera.position)||!v(u.camera.target)))throw new Error('问题里的视角无效。');return {record:r,ui:structuredClone(u)};
}
function validateWorld(raw,atlas){if(raw===null||raw===undefined)return null;const v=a=>Array.isArray(a)&&a.length===3&&a.every(n=>Number.isFinite(n)&&Math.abs(n)<1e6),keys=new Set([...atlas.nodes.map(n=>'node:'+n.id),...atlas.packs.map(p=>'pack:'+p.id),...atlas.themes.map(t=>'theme:'+t.id)]);if(!obj(raw)||!v(raw.position)||!v(raw.target)||Math.hypot(...raw.position.map((n,i)=>n-raw.target[i]))<5||raw.selected!==null&&!keys.has(raw.selected)||raw.layout!==undefined&&!['classic','network'].includes(raw.layout)||raw.cameraZoom!==undefined&&(raw.networkVersion!==49||!Number.isFinite(raw.cameraZoom)||raw.cameraZoom<.05||raw.cameraZoom>100)||raw.networkVersion!==undefined&&(raw.layout!=='network'||![47,48,49].includes(raw.networkVersion))||raw.networkView!==undefined&&(raw.layout!=='network'||!['map','relations','oblique','legacy'].includes(raw.networkView)))throw new Error('问题里的空间位置无效。');return {position:[...raw.position],target:[...raw.target],selected:raw.selected,...(raw.layout?{layout:raw.layout}:{}),...(raw.networkView?{networkView:raw.networkView}:{}),...(raw.networkVersion?{networkVersion:raw.networkVersion}:{}),...(raw.cameraZoom?{cameraZoom:raw.cameraZoom}:{})};}
export function addQuestion(state,text,context={},at=stamp()){if(typeof text!=='string'||!text.trim()||text.length>1000)throw new Error('先写下一个想继续想的问题，最多 1000 字。');state.daily??=freshDaily();const q={id:uuid(),text,at,nodeId:context.nodeId||null,scene:context.scene||null,world:context.world||null,events:[]};state.daily.questions.push(q);return q;}
export const questionDone=q=>q.events.some(e=>e.kind==='finish');
export function questionAction(state,id,kind,at=stamp()){if(!['later','finish'].includes(kind))throw new Error('未知的问题操作。');const q=state.daily.questions.find(q=>q.id===id);if(!q)throw new Error('找不到这个问题。');if(kind==='finish'&&questionDone(q))return;q.events.push(event(kind,at));}
export function pendingQuestions(state,at=new Date(),timeZone){const today=dayKey(at,timeZone);return (state.daily?.questions||[]).filter(q=>!questionDone(q)).filter(q=>{const last=q.events.at(-1);return last?.kind!=='later'||dayKey(last.at,timeZone)<today;}).sort((a,b)=>b.at.localeCompare(a.at)||a.id.localeCompare(b.id));}
export function resumeQuestion(state,id,at=stamp()){const q=state.daily.questions.find(q=>q.id===id);if(!q)throw new Error('找不到这个问题。');const scene=q.scene;if(scene){const sid=scene.record.id,current=sessionRecord(state,sid),displaced=current?captureSession(current):null;q.events.push(event('resume',at,{displaced}));const restored=mergeLesson(scene.record,current||freshLesson(sid));restored.ui=structuredClone(scene.ui);if(BRIDGES[sid])state.daily.bridges[sid]=restored;else state.lessons[sid]=restored;rememberSession(state,sid,id,at);}else q.events.push(event('resume',at,{displaced:null}));return q;}
export function completionTime(a){if(!a||!lessonSummary(a).completed)return null;return sessionTasks(a.id).map((t,i)=>a.cases[i].attempts.filter(e=>inspect(t,e.value).correct).map(e=>e.at).sort()[0]).sort().at(-1);}
export function nodeCompletionTimes(state){const out={};const save=(id,at)=>{if(at&&topicIds.includes(id)&&(!out[id]||at<out[id]))out[id]=at;};for(const id of lessonIds)save(LESSONS[id].topicId,completionTime(state.lessons?.[id]));
 for(const [id,a]of Object.entries(state.activities||{})){const first=['construct','transfer'].map(k=>[0,1].flatMap(v=>(a.evidence[`${k}:${v}`]?.attempts||[]).map(e=>e.at)).sort()[0]);if(first.every(Boolean))save(ACTIVITIES[id].topicId,first.sort().at(-1));}
 const j=state.journeys?.portions;save(ROUTE_STEPS[0].id,j?.fairFinishedAt);save(ROUTE_STEPS[1].id,j?.finishedAt);return out;
}
export function connectionTimes(state,atlas){const out={};for(const [id,b]of Object.entries(state.daily?.bridges||{})){const at=completionTime(b);if(at&&sourceBridge(id,atlas))out[bridgeEdgeKey(id)]=at;}return out;}
export function dailySummary(state,atlas,at=new Date(),timeZone){const day=dayKey(at,timeZone),nodes=nodeCompletionTimes(state),connections=connectionTimes(state,atlas);return {day,nodes:Object.entries(nodes).filter(([,t])=>dayKey(t,timeZone)===day).map(([id])=>id),connections:Object.entries(connections).filter(([,t])=>dayKey(t,timeZone)===day).map(([id])=>id),completedConnections:Object.keys(connections)};}
export function continuation(state,at=new Date(),timeZone){const q=pendingQuestions(state,at,timeZone)[0];if(q)return {kind:'question',questionId:q.id,sessionId:q.scene?.record.id||null,nodeId:q.nodeId,title:q.text};
 const last=state.daily?.continuation?.id||state.lessonContinuation,lastRecord=sessionRecord(state,last);if(lastRecord&&!lessonSummary(lastRecord).completed)return {kind:'session',sessionId:last,title:sessionMeta(last).title};
 const unfinished=[...lessonIds,...bridgeIds].map(id=>sessionRecord(state,id)).filter(a=>a&&!lessonSummary(a).completed).sort((a,b)=>b.updatedAt.localeCompare(a.updatedAt));if(unfinished[0])return {kind:'session',sessionId:unfinished[0].id,title:sessionMeta(unfinished[0].id).title};
 const done=nodeCompletionTimes(state),lastLesson=BRIDGES[last]?.to||last,route=routeFor(lastLesson)||routeFor('share');const candidates=[...route.ids,...lessonIds.filter(id=>!route.ids.includes(id))];const next=candidates.find(id=>!done[LESSONS[id].topicId]);if(next)return {kind:'session',sessionId:next,title:LESSONS[next].title};
 const bridge=bridgeIds.find(id=>!completionTime(state.daily?.bridges[id]));if(bridge)return {kind:'session',sessionId:bridge,title:BRIDGES[bridge].title};return {kind:'space',packId:route.packIds[0],title:'在这条路线再看看'};
}
export function validateDaily(raw,atlas){if(raw===undefined)return freshDaily();const fail=()=>{throw new Error('每日学习记录无效，原记录不会被覆盖。');};if(!obj(raw)||!obj(raw.bridges)||!Array.isArray(raw.questions)||raw.questions.length>300)fail();const out=freshDaily(),nodeIds=new Set(atlas.nodes.map(n=>n.id));for(const[id,b]of Object.entries(raw.bridges)){if(!sourceBridge(id,atlas))fail();out.bridges[id]=validateLesson(b,id,{allowBridge:true});}
 const ids=new Set();out.questions=raw.questions.map(q=>{if(!obj(q)||typeof q.id!=='string'||!q.id.length||q.id.length>100||ids.has(q.id)||typeof q.text!=='string'||!q.text.trim()||q.text.length>1000||!validDate(q.at)||q.nodeId!==null&&!nodeIds.has(q.nodeId)||!Array.isArray(q.events)||q.events.length>300)fail();ids.add(q.id);const scene=validateScene(q.scene);if(scene&&sessionMeta(scene.record.id).topicId!==q.nodeId)fail();const eventIds=new Set();return {id:q.id,text:q.text,at:q.at,nodeId:q.nodeId,scene,world:validateWorld(q.world,atlas),events:q.events.map(e=>{if(!obj(e)||typeof e.id!=='string'||!e.id.length||e.id.length>100||eventIds.has(e.id)||!validDate(e.at)||!['resume','later','finish'].includes(e.kind))fail();eventIds.add(e.id);return {id:e.id,kind:e.kind,at:e.at,...(e.kind==='resume'?{displaced:validateScene(e.displaced)}:{})};})};});
 const c=raw.continuation;if(c!==null&&c!==undefined){if(!obj(c)||!sessionMeta(c.id)||!validDate(c.at)||c.questionId!==null&&!ids.has(c.questionId))fail();out.continuation={id:c.id,at:c.at,questionId:c.questionId};}return out;
}
function events(a,b){const map=new Map(a.map(e=>[e.id,e]));for(const e of b)if(!map.has(e.id))map.set(e.id,e);return [...map.values()].sort((x,y)=>x.at.localeCompare(y.at));}
export function mergeDaily(current=freshDaily(),incoming=freshDaily()){const out=structuredClone(current);for(const[id,b]of Object.entries(incoming.bridges))out.bridges[id]=mergeLesson(out.bridges[id],b);const qs=new Map(out.questions.map(q=>[q.id,q]));for(const q of incoming.questions){if(qs.has(q.id))qs.get(q.id).events=events(qs.get(q.id).events,q.events);else{const copy=structuredClone(q);qs.set(q.id,copy);out.questions.push(copy);}}
 if(incoming.continuation&&(!out.continuation||incoming.continuation.at>out.continuation.at))out.continuation=structuredClone(incoming.continuation);return out;}
